import{_ as n,o as t,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Kế hoạch kỹ thuật — IMPLEMENTING","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-crawler-management/plan.md","filePath":"feature/admin-crawler-management/plan.md"}'),r={name:"feature/admin-crawler-management/plan.md"};function a(c,e,h,l,s,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ke-hoach-ky-thuat-—-implementing" tabindex="-1">Kế hoạch kỹ thuật — IMPLEMENTING <a class="header-anchor" href="#ke-hoach-ky-thuat-—-implementing" aria-label="Permalink to &quot;Kế hoạch kỹ thuật — IMPLEMENTING&quot;">​</a></h1><p>Người dùng đã duyệt triển khai dev; mọi thay đổi production vẫn qua CI/CD sau kiểm chứng.</p><h2 id="kien-truc-va-thu-tu-thuc-hien" tabindex="-1">Kiến trúc và thứ tự thực hiện <a class="header-anchor" href="#kien-truc-va-thu-tu-thuc-hien" aria-label="Permalink to &quot;Kiến trúc và thứ tự thực hiện&quot;">​</a></h2><ol><li>Chốt BA, state machine, readiness policy, publication failed-all-sources và retention secret. Đối chiếu hợp đồng tính năng cũ; không chỉnh spec cũ trước khi scope mới được duyệt.</li><li>Chuẩn hóa runtime trong dev: Dockerfile chứa collector deps/browser/libs, CPU-only NLP, image smoke test chạy non-root. Không gộp nguyên requirements crawler đang pin pydantic khác root mà chưa giải quyết tương thích. Persistent volume cho config/session/control/output/manifest; UID/GID và cấu trúc version rõ. Scheduler owner do Compose/process lifecycle quản lý, share lock/state với manual API; API startup không tự tạo nhiều scheduler. Kiểm tra tương thích và chuyển giờ UTC cũ trước timezone migration.</li><li>AI service: health checks độc lập có deadline; heartbeat worker/scheduler; secret storage adapter mã hóa có key managed riêng; session validation/version/working copy; allowlist proxy/provider; async probes có rate limit; command stop và reconciliation; event/log redaction. API health probes không download browser hoặc chạy provider tự động.</li><li>Business service: giữ requireAdmin + internal auth; facade cho endpoint mới, validate file/limit, audit command, không lưu body secret trong logs. Gateway limit/timeout và đường truyền TLS mang secret được cấu hình qua repo hạ tầng. Lựa chọn KMS/encrypted volume theo thiết lập AWS thực tế, không tự tạo key/account hoặc mở rộng IAM ngoài scope đã duyệt.</li><li>Web: mở rộng trang hiện có, reuse styles/components và hooks; group tác vụ, masked secret form, run detail inline, lý do disable đầy đủ; không tự skip nền tảng. Giữ endpoint/khu replay và graph, liên kết sang khi phù hợp thay vì nhân bản tính năng.</li><li>Chạy test theo test.md; local/staging verification bằng fixture/mock providers trước. Build immutable image, review diff, CI/CD và deploy sau approval riêng; smoke test read-only trước một run live được phép. Không lấy trạng thái production từ các lần kiểm tra trước làm bằng chứng môi trường hiện tại.</li></ol><h2 id="vung-code-du-kien" tabindex="-1">Vùng code dự kiến <a class="header-anchor" href="#vung-code-du-kien" aria-label="Permalink to &quot;Vùng code dự kiến&quot;">​</a></h2><ul><li>Web: <code>src/pages/admin/components/AdminTrendPipelinePanel.tsx</code>, control/run/settings/source components; hooks/services/types pipeline; thêm session/connection/health/run-detail components trong feature admin; <code>src/i18n/locales/vi/admin.json</code> và <code>en/admin.json</code>.</li><li>Business: AdminTrendPipelineController/Service, DTOs, ErrorCode và audit hiện có; endpoint file upload có giới hạn và role check.</li><li>AI: trend_pipeline_control, local_trend_runner, crawl_run_service, worker heartbeat và router pipeline; social_crawler run_control/pipeline_settings/stealth để chốt version và stop an toàn. Giữ publication/dedup core, chỉ thay policy đã duyệt rõ.</li><li>Infra: Compose/Dockerfile/CI/runtime mount/lifecycle/secret transport; dữ liệu runtime không commit vào Git hoặc build context.</li></ul><h2 id="du-lieu-va-migration" tabindex="-1">Dữ liệu và migration <a class="header-anchor" href="#du-lieu-va-migration" aria-label="Permalink to &quot;Dữ liệu và migration&quot;">​</a></h2><ul><li>Không dự kiến đổi domain schema PostgreSQL/Neo4j. Mở rộng metadata run/check/event với version schema, backward-compatible read.</li><li>Runtime config, history, manifests và locks chuyển sang persistent root qua setting triển khai; một lần copy/validate/backup, không purge dữ liệu cũ.</li><li>Secret file mã hóa có opaque version, active pointer và metadata. Không ghi giá trị vào Redis status, config snapshot, audit hoặc API response. Worker/browser nhận bản giải mã tối thiểu trong vùng hạn chế và dọn theo lifecycle; bản cookie browser cập nhật tách khỏi upload gốc.</li><li>Các run cũ có field thiếu vẫn đọc được. Không dùng Redis TTL làm bản lưu lịch sử duy nhất.</li></ul><h2 id="cac-moc-ban-giao" tabindex="-1">Các mốc bàn giao <a class="header-anchor" href="#cac-moc-ban-giao" aria-label="Permalink to &quot;Các mốc bàn giao&quot;">​</a></h2><ul><li>M1: runtime tái lập được + readiness chính xác (BA-02,03,19).</li><li>M2: cấu hình nguồn/session/kết nối/lịch an toàn (BA-04..10, 18).</li><li>M3: điều khiển, dừng và quan sát run hoàn chỉnh (BA-11..15); kiểm tra dữ liệu trend trên <code>/admin?view=trends</code> hiện có.</li><li>M4: P1 retry chọn lọc và cảnh báo sau khi duyệt (BA-16,20).</li></ul><p>Mỗi mốc gồm API/UI tương ứng, test, demo dev và review. Không ước lượng lịch hoàn thành trước khi chốt scope và cơ chế secret/TLS.</p><h2 id="hop-đong-trien-khai-đa-cai-trong-code-chua-thao-tac-production" tabindex="-1">Hợp đồng triển khai đã cài trong code (chưa thao tác production) <a class="header-anchor" href="#hop-đong-trien-khai-đa-cai-trong-code-chua-thao-tac-production" aria-label="Permalink to &quot;Hợp đồng triển khai đã cài trong code (chưa thao tác production)&quot;">​</a></h2><ul><li>Docker image dùng Debian bookworm, cài <code>requirements-crawler.txt</code> cùng requirements chính, cài browser ở build time dưới appuser. Entrypoint quản lý Uvicorn + một scheduler; <code>CRAWLER_SCHEDULER_ENABLED=false</code> tắt scheduler khi cần. Không cài package/browser lúc startup.</li><li>Volume <code>/app/data</code> chứa <code>CRAWLER_STATE_DIR=/app/data/crawler/control</code>, <code>CRAWLER_OUTPUT_DIR=/app/data/crawler/output</code>. <code>CRAWLER_WORK_DIR=/dev/shm/crawler</code> giữ bản session giải mã theo run/probe trong tmpfs, dọn khi run kết thúc. Không dùng volume cookie plaintext cũ làm kho upload mới.</li><li>Provision file Fernet key riêng ngoài volume chứa ciphertext, mount read-only với UID appuser, đặt <code>CRAWLER_SECRET_KEY_FILE</code>. Code không tự tạo key production. Dev/test dùng key tạm; không commit key/env/session. Upload disabled nếu key thiếu/sai. Cần bảo vệ disk/backup và key bằng cơ chế triển khai hiện có; không tạo AWS account/IAM key mới.</li><li><code>CRAWLER_PROXY_HOSTS</code>, <code>CRAWLER_TIKTOK_HOSTS</code> là allowlist chính xác do deployment quản lý. Endpoint nhập mới phải resolve ra địa chỉ public; URL redirect không được probe theo. Proxy mang credential chỉ chấp nhận HTTPS. TikTok probe cần <code>CRAWLER_TIKTOK_PROBE_PATH</code> là read-only endpoint thực tế của provider; nếu thiếu báo chưa cấu hình, không tự đoán API tốn phí.</li><li>Business <code>postSecret</code> chặn truyền secret tới AI qua HTTP ngoài loopback. Phải provision HTTPS + trust hợp lệ cho AI endpoint trước khi bật upload production, và bảo vệ các chặng edge/gateway/business mang payload. Đây là release gate; không bypass bằng cấu hình insecure. HTTP loopback local chỉ dành dev.</li><li>Migration offline: dừng collector/scheduler trước, sao lưu cây state/output cũ; chạy <code>python -m scripts.migrate_crawler_state --source &lt;old-control&gt; --target &lt;new-control&gt;</code> và tương tự cho output bằng UID service. Tool không xóa nguồn, không ghi đè file xung đột và kiểm tra lock. So sánh config/manifests/history trước startup; rollback giữ cả volume và image cũ. Nếu còn batch xử lý, chờ publication hoặc phục hồi manifest trước chuyển.</li><li>Retry P1 trong bản này tạo run mới cho các nguồn Facebook thất bại còn trong source config, có preview/confirm và dedup hiện có. Recovery interrupted run vẫn dùng ID gốc. Không cung cấp forced requeue worker/DLQ. Retry Threads/TikTok dùng lựa chọn nền tảng ở Run pipeline; chưa có retry theo từng worker batch.</li><li>Cảnh báo P1 trong trang gồm thiếu thành phần bắt buộc/scheduler, backlog queue (mặc định 100) và log run im lặng quá 1800 giây. Không gửi thông tin ra dịch vụ ngoài.</li></ul><p>Overlay opt-in nằm tại <code>docker/compose/ec2-ecr/crawler-management.compose.yaml</code>; đã kiểm tra <code>docker compose config --no-env-resolution --no-path-resolution -q</code>, chưa áp dụng. Chỉ đưa vào lệnh CI/CD sau khi provision key/TLS/migration được review. Không đổi image tag production hoặc tự bật endpoint insecure.</p><p>Chẩn đoán browser local dùng subprocess đồng bộ có timeout trong worker thread và đúng runner.python; không dùng asyncio.create_subprocess_exec vì Uvicorn Windows có thể dùng SelectorEventLoop. Dependency cài ở venv chạy service, Docker image riêng không cấp package cho venv local.</p><h2 id="sua-proxy-runtime" tabindex="-1">Sửa proxy runtime <a class="header-anchor" href="#sua-proxy-runtime" aria-label="Permalink to &quot;Sửa proxy runtime&quot;">​</a></h2><p>Thêm crawlfb.proxy_runtime dùng chung để lấy proxy KiotProxy, kiểm tra endpoint/TCP và trả mã lỗi không chứa credential. run.py chuẩn bị proxy trong tiến trình cha, truyền bằng env cho Facebook/Threads. CLI Facebook refresh trực tiếp khi retry; không dùng subprocess ghi dotenv. Tool rotate_proxy trở thành kiểm tra runtime không ghi file. Threads standalone dùng cùng resolver. Regression giả lập provider, socket và browser; không gọi provider thật.</p><h2 id="session-ram-theo-yeu-cau-2026-11-02" tabindex="-1">Session RAM theo yêu cầu (2026-11-02) <a class="header-anchor" href="#session-ram-theo-yeu-cau-2026-11-02" aria-label="Permalink to &quot;Session RAM theo yêu cầu (2026-11-02)&quot;">​</a></h2><p>Dùng store RAM có lock, version/revision và deepcopy trong AI process. Truyền snapshot session qua stdin pipe tới preflight, runner và CLI con; marker memory:facebook/threads dùng storage_state dict, không lưu cookie khi đóng browser. Scheduler gọi API hiện có để dùng chung RAM. Probe cũng dùng stdin. Legacy cookie API chuyển cùng RAM; không backup/restore Redis/file. UI mở session upload độc lập kho khóa, ghi rõ restart cần nạp lại. Một API worker sở hữu RAM (entrypoint hiện tại một worker).</p><p>Session RAM thay thế các yêu cầu file khóa/working-copy session ở phần thiết kế trước. Overlay crawler-management.compose.yaml không còn cần mount key; chỉ thêm crawler-connections.compose.yaml nếu muốn quản lý proxy/TikTok mã hóa qua UI. Các file/ciphertext session cũ không được đọc/phục hồi tự động; không tự xóa dữ liệu deployment cũ. Không tăng số API worker: RAM chỉ thuộc API process hiện tại. Sau rollout/restart admin nạp lại session.</p><h2 id="deploy-disk-guard-2026-11-02" tabindex="-1">Deploy disk guard (2026-11-02) <a class="header-anchor" href="#deploy-disk-guard-2026-11-02" aria-label="Permalink to &quot;Deploy disk guard (2026-11-02)&quot;">​</a></h2><p>Thêm scripts/prepare_deploy_disk.py: mặc định dry-run, chọn image đúng repository và không có tag thuộc repo khác; bảo vệ toàn bộ container đang chạy/đã dừng, target và image unused mới nhất. Apply bỏ từng tag bằng docker image rm không force, kiểm tra lại container trước khi xóa. Workflow nhúng script base64 qua SSM trước backup/sửa compose, kiểm tra tối thiểu 6 GiB và inode. Không tự dọn production ngoài CI/CD.</p><h2 id="sua-quyen-volume-va-chan-đoan-rollback-2026-11-02" tabindex="-1">Sửa quyền volume và chẩn đoán rollback (2026-11-02) <a class="header-anchor" href="#sua-quyen-volume-va-chan-đoan-rollback-2026-11-02" aria-label="Permalink to &quot;Sửa quyền volume và chẩn đoán rollback (2026-11-02)&quot;">​</a></h2><p>Thêm scripts.prepare_crawler_volume chạy một lần bằng root trong container compose --rm --no-deps với image mới đã pull. Lấy UID/GID appuser từ image, tạo control/output và chown/chmod cây crawler giới hạn; reject symlink/hardlink/path ngoài base. API/scheduler vẫn chạy appuser. Thêm scripts.capture_deploy_failure chỉ in trạng thái/health và các dòng startup/error đã redaction, không in Env; gọi trước rollback và không để lỗi capture cản rollback.</p><h2 id="retention-khi-rollout-that-bai-2026-11-02" tabindex="-1">Retention khi rollout thất bại (2026-11-02) <a class="header-anchor" href="#retention-khi-rollout-that-bai-2026-11-02" aria-label="Permalink to &quot;Retention khi rollout thất bại (2026-11-02)&quot;">​</a></h2><p>Trong candidates(), xác định mốc Created mới nhất của image thuộc repo đang được container tham chiếu. Chỉ chọn bản dự phòng từ image unused có Created &lt;= mốc đó; các image unused mới hơn vẫn là ứng viên cleanup. Mọi container/target/foreign tags tiếp tục được bảo vệ và recheck trước remove không force. Nếu chưa có container tham chiếu repo thì giữ retention mặc định cho initial deployment.</p><h2 id="rut-gon-run-tren-overview-2026-11-02" tabindex="-1">Rút gọn run trên overview (2026-11-02) <a class="header-anchor" href="#rut-gon-run-tren-overview-2026-11-02" aria-label="Permalink to &quot;Rút gọn run trên overview (2026-11-02)&quot;">​</a></h2><p>AdminTrendPipelineControl managed chọn active hoặc history mới nhất theo startedAt, không phụ thuộc thứ tự API. Panel hiển thị banner khi có run bất kỳ. Không sửa API hay tab lịch sử.</p><h2 id="thu-muc-worker-co-quyen-ghi-2026-11-03" tabindex="-1">Thư mục worker có quyền ghi (2026-11-03) <a class="header-anchor" href="#thu-muc-worker-co-quyen-ghi-2026-11-03" aria-label="Permalink to &quot;Thư mục worker có quyền ghi (2026-11-03)&quot;">​</a></h2><p>Đổi default local thành data/crawler/trend_runs; Docker và EC2 Compose dùng TREND_RUN_DIR=/app/data/crawler/trend_runs. Workflow set environment override trước init/recreate để env_file cũ không trỏ về data/trend_runs. Init tạo thư mục với UID/GID appuser trong phạm vi crawler.</p><h2 id="cai-browser-on-đinh-trong-build-2026-11-03" tabindex="-1">Cài browser ổn định trong build (2026-11-03) <a class="header-anchor" href="#cai-browser-on-đinh-trong-build-2026-11-03" aria-label="Permalink to &quot;Cài browser ổn định trong build (2026-11-03)&quot;">​</a></h2><p>Installer riêng gọi ensure_binary(browser_version=get_chromium_version()) để dùng nhánh pinned không tạo background update threads; Docker chạy installer rồi info --quick với faulthandler. Giữ layer browser trước COPY source để bảo toàn cache.</p><p>Runtime ENV đặt sau dependency layer; data/crawler/ bị loại khỏi build context để không đưa dữ liệu run local vào image.</p><h2 id="gioi-han-ram-ai-4-5-gib-2026-11-03" tabindex="-1">Giới hạn RAM AI 4.5 GiB (2026-11-03) <a class="header-anchor" href="#gioi-han-ram-ai-4-5-gib-2026-11-03" aria-label="Permalink to &quot;Giới hạn RAM AI 4.5 GiB (2026-11-03)&quot;">​</a></h2><p>Đặt ai-service.mem_limit=4608m trong EC2 Compose và overlay crawler. Workflow AI cập nhật mem_limit cùng image/TREND_RUN_DIR trước recreate, có sẵn backup/rollback compose. Không thay limit service khác, không đổi Docker image/browser code.</p>',35)])])}const p=n(r,[["render",a]]);export{g as __pageData,p as default};
